import assert from 'node:assert/strict';
import { keccak256 } from 'ethers';
import { createRevmStrictSimulationTransport } from './src/searcher/revm-strict-simulation-transport.ts';
import { RevmFatalError, RevmStrictError } from './src/searcher/revm-sim-client.ts';
import { buildSubscriptCalldata } from './src/shared/executor/botvm-program-entry.ts';
const addr = x => '0x' + x.repeat(40), hash = x => '0x' + x.repeat(64);
const executor = addr('a'), origin = addr('b'), token = addr('c');
const source = { number: 101, hash: hash('1'), generation: 1 };
const pin = { chainId: 1, blockHash: source.hash, stateRoot: hash('2') };
const code = { code: '0x60006000f3', keccak256: keccak256('0x60006000f3') };
const invocation = { source, callerAuthority: { executor, transactionOrigin: origin },
  request: { id: 'review-program', kind: 'effect-delta-simulation',
    call: { caller: {kind:'executor'}, executionMode:'executor-program', to:executor,
      data:buildSubscriptCalldata(new Uint8Array([0])) },
    overrideIntent: { caller:{kind:'executor'}, tokenBalances:[{token,amount:1n}] },
    observe:['return-data','revert-data'] } };
const prefix = { executor, calldata: invocation.request.call.data, inputToken:token,inputAmount:1n };
const cases = [
  {name:'standalone-program-absent',prefix:false,expected:'incomplete'},
  {name:'prefix-program-absent',prefix:true,expected:'incomplete'},
  {name:'prefix-program-null',prefix:true,metadata:null,expected:'reverted-as-declared'},
  {name:'prefix-program-nested',prefix:true,metadata:'OutOfGas',expected:'incomplete'},
  {name:'prefix-stage-nested',prefix:true,phase:'preCall',metadata:'OutOfGas',expected:'incomplete'},
  {name:'prefix-absent-wrong-code-proof',prefix:true,tamper:'code',expected:'protocol-fault'},
  {name:'prefix-nested-wrong-source',prefix:true,metadata:'OutOfGas',tamper:'source',expected:'source-fault'},
  {name:'prefix-malformed-metadata',prefix:true,metadata:257,expected:'protocol-fault'},
];
const results=[];
for (const c of cases) {
  const fatals=[]; let wire;
  const transport=createRevmStrictSimulationTransport({rpcUrl:'http://offline.invalid',executionGasLimit:100000,executorRuntimeCode:code,
    leaseFor:async()=>({source,sourcePin:pin,closeAndDrain:async()=>assert.fail('unexpected lease close'),
      strictSimulate:async req=>{
        wire=req;
        const outcome={kind:'Revert',phase:c.phase??'main',output:'0xdeadbeef',
          ...(c.phase==='preCall'?{preCallIndex:0}:{}),
          ...(Object.hasOwn(c,'metadata')?{nestedHalt:c.metadata}:{})};
        return {ok:true,success:false,output:outcome.output,revertReason:outcome.output,gasUsed:'123',latencyMs:1,
          sourceAttestation:{kind:'node-attested',...pin,blockHash:c.tamper==='source'?hash('9'):pin.blockHash,blockNumber:source.number,parentHash:hash('3')},
          strict:{outcome,executionGasUsed:'123',tokenDeltas:[],nativeDeltas:[],totalSupplyDeltas:[],logs:[],
            counterfactualExecutorCode:{address:executor,keccak256:c.tamper==='code'?hash('4'):code.keccak256}}};
      }}),onFatal:reason=>fatals.push(reason)});
  let actual,detail;
  try {
    const value=c.prefix?await transport.simulatePrefix({...invocation,prefix}):await transport.simulate(invocation);
    actual=value.completion??'success'; detail=value;
  } catch(e) {
    actual=e instanceof RevmFatalError?e.fatal.kind:e instanceof RevmStrictError&&e.kind==='execution'?'incomplete':e.code??e.name;
    detail={name:e.name,kind:e.kind,code:e.code,exactPrefixFailure:e.exactPrefixFailure};
    assert.notEqual(e.code,'CALL_EXCEPTION');
  }
  assert.equal(wire.to,executor);
  assert.equal(wire.executorRuntimeCode===undefined,c.prefix);
  if(c.prefix) assert.equal(wire.trialPrefix.executorRuntimeCode.keccak256,code.keccak256);
  if(actual==='incomplete') assert.deepEqual(fatals,[]);
  if(c.name==='prefix-stage-nested') assert.deepEqual(detail.exactPrefixFailure,{kind:'Revert',phase:'preCall',preCallIndex:0,output:'0xdeadbeef',nestedHalt:'OutOfGas'});
  results.push({name:c.name,expected:c.expected,actual,pass:actual===c.expected,detail});
}
console.log(JSON.stringify({check:'independent-offline-prefix-program-provenance',cases:results,
  passed:results.filter(r=>r.pass).length,failed:results.filter(r=>!r.pass).length},null,2));
process.exitCode=results.some(r=>!r.pass)?1:0;
